var e={"updates.title":`Обновления`,"updates.sub":`Кольца обновлений, открытые обновления безопасности и версии пакетов`,"updates.palette.rings":`Открыть кольца обновлений`,"updates.palette.cves":`Показать открытые CVE`,"updates.tab.rings":`Кольца`,"updates.tab.security":`Безопасность`,"updates.tab.versions":`Версии пакетов`,"updates.rings.title":`Кольца обновлений`,"updates.rings.sub":`Волна начинается в первом кольце. Кольцо N получает её, когда она старше его отсрочки и предыдущее кольцо её уже получило. Приостановленное кольцо ничего не устанавливает и задерживает кольца за ним.`,"updates.rings.none":`Колец обновлений пока нет`,"updates.rings.noneBody":`Без колец устройства устанавливают обновления в каждом окне. Создайте, например, пилотное, раннее и широкое.`,"updates.rings.unassigned":{one:`{count} устройство не входит ни в одно кольцо.`,few:`{count} устройства не входят ни в одно кольцо.`,many:`{count} устройств не входят ни в одно кольцо.`,other:`{count} устройства не входят ни в одно кольцо.`},"updates.ring.add":`Добавить кольцо`,"updates.ring.edit":`Изменить кольцо`,"updates.ring.formSub":`Устройство относится к первому подходящему кольцу: по тегу, группе каталога, блупринту или как любое другое устройство.`,"updates.ring.name":`Название`,"updates.ring.position":`Порядок`,"updates.ring.positionHelp":`Меньшие номера идут первыми.`,"updates.ring.members":`Участники`,"updates.ring.deferral":`Отсрочка (дни)`,"updates.ring.deferralHelp":`Дней после начала волны, прежде чем она дойдёт до этого кольца.`,"updates.ring.waveDays":`Новая волна каждые (дни)`,"updates.ring.waveDaysHelp":`Только первое кольцо: запускает волну автоматически; 0 означает только вручную.`,"updates.ring.tags":`Теги`,"updates.ring.groups":`Группы каталога`,"updates.ring.listHelp":`Через запятую.`,"updates.ring.blueprint":`Блупринт`,"updates.ring.blueprintHelp":`Устройства этого блупринта и наследующих от него блупринтов.`,"updates.ring.noBlueprint":`Без блупринта`,"updates.ring.all":`Все прочие устройства`,"updates.ring.requireApproval":`Одобрение перед каждой волной`,"updates.ring.wave":`Волна`,"updates.ring.waveN":`Волна {wave}`,"updates.ring.noWave":`волн пока нет`,"updates.ring.devices":`Устройства`,"updates.ring.paused":`приостановлено`,"updates.ring.active":`активно`,"updates.ring.approvalBadge":`одобрено до волны {wave}`,"updates.ring.every":{one:`волна каждый {count} день`,few:`волна каждые {count} дня`,many:`волна каждые {count} дней`,other:`волна каждые {count} дня`},"updates.ring.manual":`волны вручную`,"updates.ring.days":{one:`{count} день`,few:`{count} дня`,many:`{count} дней`,other:`{count} дня`},"updates.ring.approve":`Одобрить`,"updates.ring.pause":`Приостановить`,"updates.ring.resume":`Возобновить`,"updates.ring.blueprintN":`Блупринт #{id}`,"updates.ring.nobody":`нет критериев`,"updates.ring.saved":`Кольцо сохранено`,"updates.ring.deleted":`Кольцо удалено`,"updates.ring.deleteTitle":`Удалить кольцо {name}?`,"updates.ring.deleteBody":`Со следующей синхронизации его устройства попадут в следующее подходящее кольцо или ни в какое.`,"updates.ring.done.pause":`Кольцо {name} приостановлено`,"updates.ring.done.resume":`Кольцо {name} возобновлено`,"updates.ring.done.approve":`Кольцо {name} одобрено`,"updates.wave.start":`Начать новую волну`,"updates.wave.started":`Волна {wave} начата`,"updates.waves.title":`Волны`,"updates.waves.sub":`Последние 20 волн. Волна устанавливает то, что предлагают репозитории в момент её выполнения на устройстве.`,"updates.waves.at":`Начата`,"updates.waves.by":`Кем`,"updates.waves.none":`Волн ещё не было.`,"updates.rules.title":`Правила по источникам`,"updates.rules.body":`Режим, окно и кольцо для каждого источника (обновления безопасности, все обновления ОС, сторонние репозитории, Flatpak) задаются в политике com.limdm.updates в правилах по источникам. Там же задаётся, через сколько дней ожидающие обновления безопасности не проходят проверку updates.security_age.`,"updates.rules.link":`Открыть библиотеку`,"updates.kpi.security":`Устройства с обновлениями безопасности`,"updates.kpi.pending":`Устройства с ожидающими обновлениями`,"updates.kpi.cves":`Открытые CVE`,"updates.kpi.reporting":`Устройства, сообщающие об обновлениях`,"updates.cves.title":`Открытые CVE`,"updates.cves.sub":`CVE с доступным исправлением: из бюллетеней менеджера пакетов (dnf, zypper) и, если включено, из данных безопасности Debian и Ubuntu. Выберите CVE, чтобы увидеть затронутые устройства.`,"updates.cves.none":`Открытых CVE нет`,"updates.cves.noneBody":`Fedora, RHEL и SUSE сообщают CVE своих ожидающих обновлений безопасности. Для Debian и Ubuntu включите данные CVE в настройках.`,"updates.cves.noIds":{one:`{count} ожидающее обновление безопасности без ID CVE (apt).`,few:`{count} ожидающих обновления безопасности без ID CVE (apt).`,many:`{count} ожидающих обновлений безопасности без ID CVE (apt).`,other:`{count} ожидающего обновления безопасности без ID CVE (apt).`},"updates.cves.devices":`Устройства с {cve}`,"updates.cves.noDevices":`Ни одно устройство не сообщает об этой CVE.`,"updates.pkgs.title":`Ожидающие обновления`,"updates.pkgs.sub":`По пакетам, сначала обновления безопасности, 300 самых частых.`,"updates.pkgs.none":`Ожидающих обновлений нет.`,"updates.versions.title":`Установленные версии`,"updates.versions.sub":`Какая версия пакета установлена на скольких устройствах.`,"updates.versions.show":`Показать`,"updates.versions.pick":`Выберите пакет`,"updates.versions.pickBody":`Введите имя пакета, например openssl.`,"updates.versions.none":`Ни на одном устройстве не установлен {name}.`,"updates.severity":`Серьёзность`,"updates.devicesCol":`Устройства`,"updates.device":`Устройство`,"updates.packages":`Пакеты`,"updates.package":`Пакет`,"updates.version":`Версия`,"updates.arch":`Архитектура`,"updates.sourceCol":`Источник`,"updates.security":`Безопасность`,"updates.no":`нет`,"updates.unknown":`неизвестно`,"updates.source.os_security":`Обновления безопасности`,"updates.source.os_all":`Система`,"updates.source.third_party":`Сторонние`,"updates.source.flatpak":`Flatpak`,"updates.result.installed":`установлено`,"updates.result.no_updates":`нет обновлений`,"updates.result.failed":`ошибка`,"updates.result.unsupported":`не поддерживается`,"updates.dev.ring":`Кольцо обновлений`,"updates.dev.noRing":`Не в кольце: устанавливает в каждом окне.`,"updates.dev.toRings":`Открыть кольца обновлений`,"updates.dev.summary":`Статус`,"updates.dev.pendingN":{one:`{count} обновление ОС ожидает`,few:`{count} обновления ОС ожидают`,many:`{count} обновлений ОС ожидают`,other:`{count} обновления ОС ожидают`},"updates.dev.securityN":{one:`из них {count} обновление безопасности`,few:`из них {count} обновления безопасности`,many:`из них {count} обновлений безопасности`,other:`из них {count} обновления безопасности`},"updates.dev.since":`Обновления безопасности ожидают с {at}`,"updates.dev.error":`Статус обновлений неизвестен: {error}`,"updates.dev.noReport":`Агент ещё не сообщил статус обновлений; старые агенты его не сообщают.`,"updates.dev.runs":`Последние запуски`,"updates.dev.runsSub":`Последний запуск по каждому источнику. «Нет обновлений» значит, что ничего не изменилось.`,"updates.dev.at":`Время`,"updates.dev.result":`Результат`,"updates.dev.detail":`Вывод`,"updates.dev.count":{one:`{count} пакет`,few:`{count} пакета`,many:`{count} пакетов`,other:`{count} пакета`},"updates.dev.noRuns":`Запусков пока нет.`,"updates.dev.pending":`Ожидающие обновления`,"updates.dev.pendingSub":`По данным менеджера пакетов устройства, обновляется ежечасно.`,"updates.dev.current":`Установлено`,"updates.dev.candidate":`Доступно`,"updates.dev.patch":`Патч`,"updates.dev.none":`Нет ожидающих обновлений`,"updates.dev.noneBody":`Устройство актуально относительно своих репозиториев.`,"updates.dev.hold":`Зафиксировать версию`,"updates.dev.release":`Снять фиксацию`,"updates.dev.downgrade":`Откатить версию`,"updates.dev.holdTitle":`Зафиксировать {name} на установленной версии?`,"updates.dev.holdBody":`apt-mark hold, dnf versionlock или zypper addlock. Arch и Alpine это не поддерживают.`,"updates.dev.releaseTitle":`Снова разрешить обновление {name}?`,"updates.dev.releaseBody":`Снимает фиксацию; следующий запуск обновит пакет.`,"updates.dev.downgradeTitle":`Откатить {name}?`,"updates.dev.downgradeBody":`Устанавливает самую новую из более старых версий из репозиториев и фиксирует пакет на ней. Только Debian, Ubuntu и dnf; старая версия должна быть в репозитории.`,"updates.dev.downgradeTo":`Устанавливает версию {version} и фиксирует пакет на ней. Только Debian, Ubuntu и dnf.`,"updates.dev.rollback":`Откат`,"updates.dev.rollbackSub":`Зафиксируйте пакет или откатите его на более старую версию. При одобрении по принципу четырёх глаз откат требует второго администратора.`,"updates.dev.versionHelp":`Пусто: самая новая из более старых версий.`,"updates.feeds.httpsOnly":`Только адреса https.`,"updates.feeds.maxRange":`От 0 до 4096.`,"updates.feeds.settingsSub":`Debian, Ubuntu, Arch и Alpine не сообщают ID CVE для своих обновлений. Для них сервер раз в день загружает данные безопасности дистрибутивов и сопоставляет их с установленными версиями пакетов. Устройства ничего не загружают.`,"updates.feeds.title":`Данные безопасности`,"updates.feeds.help":`По умолчанию выключено: сервер получает данные от третьих сторон. Дистрибутив загружается, только пока его использует хотя бы одно устройство. После сбоя остаются последние данные.`,"updates.feeds.enabled":`Загружать ежедневно`,"updates.feeds.urlHelp":`Пусто: публичный адрес; подойдёт и собственное зеркало.`,"updates.feeds.maxMB":`Наибольшая загрузка (МБ)`,"updates.feeds.maxMBHelp":`Пусто или 0 означает 1024.`,"updates.feeds.toState":`Состояние импорта в «Обновления», «Безопасность»`,"updates.feeds.state":`Данные CVE для Debian, Ubuntu, Arch и Alpine`,"updates.feeds.stateSub":`Ежедневный импорт данных безопасности. При неудачном импорте остаются последние данные.`,"updates.feeds.off":`Всё выключено. Без этих данных Debian, Ubuntu, Arch и Alpine не показывают ID CVE. Включите их в «Настройки», «Данные CVE».`,"updates.feeds.settings":`Настройки`,"updates.feeds.started":`Импорт запущен`,"updates.feeds.running":`Импорт выполняется`,"updates.feeds.refresh":`Обновить сейчас`,"updates.feeds.source":`Источник`,"updates.feeds.fetched":`Последняя загрузка`,"updates.feeds.rows":`Записи`,"updates.feeds.error":`Последняя ошибка`,"updates.feeds.distro.debian":`Debian Security Tracker`,"updates.feeds.distro.ubuntu":`Ubuntu (OSV)`,"updates.feeds.never":`никогда`,"updates.dev.vulns":`Известные уязвимости`,"updates.dev.vulnsSub":`По данным безопасности Debian и Ubuntu: установленная версия старше исправленной.`,"updates.dev.fixed":`Исправлено в`,"updates.feeds.distro.arch":`Arch Security Tracker`,"updates.feeds.distro.alpine":`Alpine secdb`,"updates.feeds.url.debian":`Адрес Debian Security Tracker (JSON)`,"updates.feeds.url.ubuntu":`Адрес экспорта Ubuntu OSV (zip)`,"updates.feeds.url.arch":`Адрес трекера Arch (issues/all.json)`,"updates.feeds.url.alpine":`Базовый адрес Alpine secdb`,"updates.feeds.about.debian":`Исправленные CVE по выпускам и исходным пакетам со срочностью.`,"updates.feeds.about.ubuntu":`Данные OSV от Canonical: исправленные CVE по выпускам с приоритетом Ubuntu.`,"updates.feeds.about.arch":`Список AVG: пакеты, исправленная версия, серьёзность и CVE. У Arch нет выпусков.`,"updates.feeds.about.alpine":`secfixes из main и community, по веткам, которые сообщают устройства Alpine (v3.20, edge). Без серьёзности.`,"updates.feeds.disabled":`выкл.`,"updates.feeds.distro.kev":`CISA KEV (эксплуатируемые)`,"updates.feeds.url.kev":`URL списка KEV (JSON)`,"updates.feeds.about.kev":`CVE, которые точно эксплуатируются (CISA). Отмечает их в «Уязвимостях». Небольшой файл, не зависит от дистрибутивов.`,"updates.feeds.skipped":`нет устройств, пропущено`,"updates.feeds.skippedHelp":`Ни одно устройство не использует этот дистрибутив: сервер загрузит данные, когда такое появится.`};export{e as default};